fn seeded(seed:u64)->sha3::Shake256Reader{let mut h=Shake256::default();h.update(b"phase-localization-research-v1");h.update(&seed.to_le_bytes());h.finalize_xof()}
fn main(){let a:Vec<_>=std::env::args().collect();let ops=load_ops(&a[1]).unwrap();let(nq,nb,_,regs)=analyze_ops(ops.iter());let marks:std::collections::BTreeSet<usize>=std::fs::read_to_string(&a[3]).unwrap().lines().map(|x|x.parse().unwrap()).collect();let curve=secp256k1();let mut dummy=seeded(0);let mut initial=Simulator::new(nq as usize,nb as usize,&mut dummy);let mut expected=Vec::new();for(lane,line)in std::fs::read_to_string(&a[2]).unwrap().lines().enumerate(){let v:Vec<_>=line.split_whitespace().collect();let k1=U256::from_str_radix(v[1].trim_start_matches("0x"),16).unwrap();let k2=U256::from_str_radix(v[2].trim_start_matches("0x"),16).unwrap();let p=curve.mul(curve.gx,curve.gy,k1);let q=curve.mul(curve.gx,curve.gy,k2);let e=curve.add(p.0,p.1,q.0,q.1);for(reg,value)in regs[..4].iter().zip([p.0,p.1,q.0,q.1]){initial.set_register(reg,value,lane);}expected.push(e);}let iq=initial.qubits.clone();let ib=initial.bits.clone();drop(initial);let timer=std::time::Instant::now();for seed in 0..8{let mut rng=seeded(seed);let mut rr=rng.clone();let mut s=observed::ObservedSimulator::new(nq as usize,nb as usize,&mut rng);s.qubits.copy_from_slice(&iq);s.bits.copy_from_slice(&ib);s.apply_iter(ops.iter(),&marks);let mut reference=Simulator::new(nq as usize,nb as usize,&mut rr);reference.qubits.copy_from_slice(&iq);reference.bits.copy_from_slice(&ib);reference.apply_iter(ops.iter());assert_eq!(s.qubits,reference.qubits);assert_eq!(s.bits,reference.bits);assert_eq!(s.phase,reference.phase);assert_eq!(s.stats.toffoli_gates,reference.stats.toffoli_gates);let mut x=[0u8;64];let mut y=x;XofReader::read(s.xof,&mut x);XofReader::read(reference.xof,&mut y);assert_eq!(x,y);let mut value=0u64;for(lane,e)in expected.iter().enumerate(){if s.get_register(&regs[0],lane)!=e.0||s.get_register(&regs[1],lane)!=e.1{value|=1<<lane;}}println!("{}",serde_json::json!({"seed":seed,"phase_hex":format!("{:016x}",s.phase),"value_hex":format!("{value:016x}"),"trace":s.trace,"protected_all_q_b_phase_rng_stats_equal":true,"seconds":timer.elapsed().as_secs_f64()}));}}
